import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"双调·水仙子访梅孤山","description":"","frontmatter":{"title":"双调·水仙子访梅孤山","date":"2026-11-11T00:00:00.000Z","seq":13,"categories":["美文","元曲"],"collection":"《元曲 · 张可久》","tags":["元曲","元"],"poem":true,"author":"张可久","source_book":"元曲"},"headers":[],"relativePath":"blogs/元曲·张可久/双调·水仙子访梅孤山.md","filePath":"blogs/元曲·张可久/双调·水仙子访梅孤山.md"}'),o={name:"blogs/元曲·张可久/双调·水仙子访梅孤山.md"};function c(l,a,n,m,_,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="双调·水仙子访梅孤山" tabindex="-1">双调·水仙子访梅孤山 <a class="header-anchor" href="#双调·水仙子访梅孤山" aria-label="Permalink to &quot;双调·水仙子访梅孤山&quot;">​</a></h1><p class="poem-meta">元 · 张可久　·　张可久</p><div class="poem"><p class="poem-stanza">苍苔封了岁寒枝，翠袖闲来日暮时，黄昏说尽平生事。</p><p class="poem-stanza">西湖林处士，想当年鹤骨松姿。</p><p class="poem-stanza">花下孤山寺，水边新月儿，慰我相思。</p><p class="poem-stanza">湖上晚归二首桃花马上石榴裙，竹叶樽前玉树春，荔枝香里江梅韵。</p><p class="poem-stanza">风流比太真，索新词缠住诗人。</p><p class="poem-stanza">醉眼空银汉，歌声度锦云，凉月黄昏。</p><p class="poem-stanza">佳人微醉脱金钗，恶客佯狂饮绣鞋，小鬟催去褰罗带。</p><p class="poem-stanza">花寒月满街，荡湖光影转楼台。</p><p class="poem-stanza">未了鸳鸯债，枉教鸥鹭猜，明日重来。</p><p class="poem-stanza">清明小集红香缭绕柳围花，翠袖殷勤酒当茶，游春三月清明假。</p><p class="poem-stanza">香尘随去马，小帘栊绿水人家。</p><p class="poem-stanza">弹仙吕六幺遍，笑女童双髻丫，纤手琵琶。</p><p class="poem-stanza">苏堤晚兴翠帘堤上小肩舆，乌帽风前醉老夫，浸冰壶云锦高低树。</p><p class="poem-stanza">笑王维作画图，步凌波红粉相扶。</p><p class="poem-stanza">罗裙酒污，兰舟棹举，月上西湖。</p><p class="poem-stanza">湖上小隐二首自由湖上水云身，烂漫花前莺燕春，萧疏命里功名分。</p><p class="poem-stanza">乐琴书桑苎村，掩柴门长日无人。</p><p class="poem-stanza">蕉叶权歌扇，榴花当舞裙，一笑开樽。</p><p class="poem-stanza">梦随流水过前滩，喜共闲云归故山，倚筇和靖坟前看。</p><p class="poem-stanza">把梅花多处拣，盖深深茅屋三间。</p><p class="poem-stanza">歌白石烂，赋行路难，紧闭柴关。</p><p class="poem-stanza">春行即事绿笺香露洒蕉花，翠线晴风绽柳芽，游人三月湖山下。</p><p class="poem-stanza">六桥边争系马，江南第一所繁华。</p><p class="poem-stanza">金碧王维画，管弦苏小家，酒船回落日归鸦。</p><p class="poem-stanza">孤山宴集长桥卧柳枕苍烟，远水揉蓝洗暮天，画图千古西施面。</p><p class="poem-stanza">相逢越少年，问孤山何处逋仙？吾与二三子，来游六一泉，载酒梅边。</p></div>',3)])])}const d=s(o,[["render",c]]);export{i as __pageData,d as default};
